class TodoList {
    struct Task { int id, user, due; string description; vector<string> tags; bool done; };
    vector<Task> tasks;
    int nextId = 1;
public:
    TodoList() {}
    int addTask(int userId, string taskDescription, int dueDate, vector<string> tags) {
        tasks.push_back({nextId, userId, dueDate, taskDescription, tags, false});
        return nextId++;
    }
    vector<string> getAllTasks(int userId) { return getTasksForTag(userId, "", false); }
    vector<string> getTasksForTag(int userId, string tag) { return getTasksForTag(userId, tag, true); }
    void completeTask(int userId, int taskId) {
        for (auto& t : tasks) if (t.id == taskId && t.user == userId) t.done = true;
    }
private:
    vector<string> getTasksForTag(int userId, const string& tag, bool filter) {
        vector<const Task*> selected;
        for (const auto& t : tasks) {
            if (t.user != userId || t.done) continue;
            if (filter && find(t.tags.begin(), t.tags.end(), tag) == t.tags.end()) continue;
            selected.push_back(&t);
        }
        sort(selected.begin(), selected.end(), [](const Task* a, const Task* b) {
            return a->due != b->due ? a->due < b->due : a->id < b->id;
        });
        vector<string> result;
        for (auto t : selected) result.push_back(t->description);
        return result;
    }
};
